import heapq

class Solution:
    def maxScore(self, nums1: list[int], nums2: list[int], k: int) -> int:
        pairs = sorted(zip(nums2, nums1), reverse=True)
        pq = []
        total = 0
        ans = 0
        for n2, n1 in pairs:
            heapq.heappush(pq, n1)
            total += n1
            if len(pq) > k:
                total -= heapq.heappop(pq)
            if len(pq) == k:
                ans = max(ans, total * n2)
        return ans

class Solution {
public:
    long long maxScore(std::vector<int>& nums1, std::vector<int>& nums2, int k) {
        int n = nums1.size();
        std::vector<std::pair<int, int>> pairs(n);
        for (int i = 0; i < n; ++i) pairs[i] = {nums2[i], nums1[i]};
        std::sort(pairs.rbegin(), pairs.rend());

        std::priority_queue<int, std::vector<int>, std::greater<int>> pq;
        long long total = 0, ans = 0;
        for (const auto& [n2, n1] : pairs) {
            pq.push(n1);
            total += n1;
            if ((int)pq.size() > k) {
                total -= pq.top();
                pq.pop();
            }
            if ((int)pq.size() == k) {
                ans = std::max(ans, total * n2);
            }
        }
        return ans;
    }
};

class Solution {
    public long maxScore(int[] nums1, int[] nums2, int k) {
        int n = nums1.length;
        int[][] pairs = new int[n][2];
        for (int i = 0; i < n; i++) {
            pairs[i][0] = nums2[i];
            pairs[i][1] = nums1[i];
        }
        java.util.Arrays.sort(pairs, (a, b) -> Integer.compare(b[0], a[0]));

        java.util.PriorityQueue<Integer> pq = new java.util.PriorityQueue<>();
        long total = 0, ans = 0;
        for (int[] p : pairs) {
            int n2 = p[0], n1 = p[1];
            pq.offer(n1);
            total += n1;
            if (pq.size() > k) {
                total -= pq.poll();
            }
            if (pq.size() == k) {
                ans = Math.max(ans, total * n2);
            }
        }
        return ans;
    }
}

var maxScore = function(nums1, nums2, k) {
    class MinHeap {
        constructor() { this.data = []; }
        push(val) {
            this.data.push(val);
            this.up(this.data.length - 1);
        }
        pop() {
            const top = this.data[0];
            const bottom = this.data.pop();
            if (this.data.length > 0) {
                this.data[0] = bottom;
                this.down(0);
            }
            return top;
        }
        size() { return this.data.length; }
        up(i) {
            while (i > 0) {
                const p = (i - 1) >> 1;
                if (this.data[i] < this.data[p]) {
                    [this.data[i], this.data[p]] = [this.data[p], this.data[i]];
                    i = p;
                } else break;
            }
        }
        down(i) {
            const len = this.data.length;
            while ((i << 1) + 1 < len) {
                let left = (i << 1) + 1, right = left + 1, best = i;
                if (left < len && this.data[left] < this.data[best]) best = left;
                if (right < len && this.data[right] < this.data[best]) best = right;
                if (best !== i) {
                    [this.data[i], this.data[best]] = [this.data[best], this.data[i]];
                    i = best;
                } else break;
            }
        }
    }

    const n = nums1.length;
    const pairs = new Array(n);
    for (let i = 0; i < n; i++) pairs[i] = [nums2[i], nums1[i]];
    pairs.sort((a, b) => b[0] - a[0]);

    const pq = new MinHeap();
    let total = 0n, ans = 0n;
    for (const [n2, n1] of pairs) {
        pq.push(n1);
        total += BigInt(n1);
        if (pq.size() > k) {
            total -= BigInt(pq.pop());
        }
        if (pq.size() === k) {
            const cur = total * BigInt(n2);
            if (cur > ans) ans = cur;
        }
    }
    return Number(ans);
};
